    private static void put(String province,String... cities){DATA.put(province,cities);}
    static String[] provinces(){return DATA.keySet().toArray(new String[0]);}
    static String[] cities(String province){String[] values=DATA.get(province);return values==null?new String[0]:values.clone();}
    static int indexOfProvince(String value){int i=0;for(String province:DATA.keySet()){if(province.equals(value))return i;i++;}return 0;}
    static int indexOfCity(String province,String value){String[] cities=cities(province);for(int i=0;i<cities.length;i++)if(cities[i].equals(value))return i;return 0;}
    static Map<String,String[]> snapshot(){return new LinkedHashMap<>(DATA);}
